<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';import SearchableCombobox from '@/components/SearchableCombobox.vue';import {Head,Link,useForm} from '@inertiajs/vue3';import {ArrowLeft,Boxes,ClipboardCheck,History,PackageCheck,ShoppingCart,UserRound} from 'lucide-vue-next';import {computed,ref} from 'vue';
const p=defineProps<{project:any;orders:any;stats:any;users:any[]}>();const tab=ref('overview');const current=computed(()=>p.project.current_responsible_assignment);const options=computed(()=>p.users.map(u=>({value:String(u.id),label:u.name,description:[u.email,u.role?.name].filter(Boolean).join(' · ')})));const assignment=useForm({user_id:'',starts_at:new Date().toISOString().slice(0,10),current_ends_at:''});
function assign(){assignment.post(route('admin.projects.responsibles.store',p.project.id),{preserveScroll:true,onSuccess:()=>assignment.reset()})}const date=(v:any)=>v?new Date(v).toLocaleDateString('fr-FR'):'—';const number=(v:any)=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(Number(v||0));const money=(v:any)=>number(v)+' FCFA';
</script>
<template><Head :title="project.name"/><AppLayout :breadcrumbs="[{title:'Administration',href:'#'},{title:'Chantiers',href:route('admin.projects.index')},{title:project.code,href:'#'}]"><div class="space-y-6 p-6 lg:p-8">
<header><Link :href="route('admin.projects.index')" class="mb-4 inline-flex items-center gap-2 text-sm font-semibold text-slate-700 hover:text-slate-950"><ArrowLeft class="h-4 w-4"/> Retour aux chantiers</Link><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-sm font-semibold text-amber-700">{{project.code}}</p><h1 class="text-3xl font-bold text-slate-950">{{project.name}}</h1></div><span class="rounded-full bg-emerald-100 px-3 py-1 text-sm font-semibold text-emerald-800">{{project.is_active?'Actif':'Inactif'}}</span></div></header>
<nav class="flex gap-1 rounded-xl bg-slate-200/70 p-1"><button class="tab" :class="tab==='overview'&&'active'" @click="tab='overview'"><ClipboardCheck class="h-4 w-4"/> Vue d’ensemble</button><button class="tab" :class="tab==='history'&&'active'" @click="tab='history'"><History class="h-4 w-4"/> Historique des responsables</button></nav>
<template v-if="tab==='overview'"><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><article class="stat"><ShoppingCart class="icon text-blue-700"/><div><strong>{{stats.orders}}</strong><span>Bons de commande</span></div></article><article class="stat"><PackageCheck class="icon text-emerald-700"/><div><strong>{{stats.receptions}}</strong><span>Réceptions · {{number(stats.received_quantity)}} unités</span></div></article><article class="stat"><Boxes class="icon text-orange-700"/><div><strong>{{stats.transfers}}</strong><span>Transferts · {{number(stats.transferred_quantity)}} unités</span></div></article><article class="stat"><ClipboardCheck class="icon text-violet-700"/><div><strong>{{money(stats.order_amount)}}</strong><span>Montant commandé</span></div></article></div>
<div class="grid gap-6 xl:grid-cols-[1fr_380px]"><section class="card overflow-hidden"><div class="border-b border-slate-200 p-5"><h2 class="text-lg font-bold text-slate-950">Bons de commande liés</h2><p class="text-sm text-slate-600">{{stats.approved_orders}} commande(s) approuvée(s)</p></div><div class="overflow-x-auto"><table class="w-full min-w-[650px] text-left"><thead class="bg-slate-50 text-xs uppercase text-slate-700"><tr><th class="cell">Bon</th><th class="cell">Demandeur</th><th class="cell">Statut</th><th class="cell text-right">Montant</th><th class="cell"></th></tr></thead><tbody class="divide-y divide-slate-200"><tr v-for="order in orders.data" :key="order.id"><td class="cell"><strong class="text-slate-950">{{order.order_number||order.reference||('#'+order.id)}}</strong><p class="text-xs text-slate-600">{{order.title}}</p></td><td class="cell text-sm text-slate-800">{{order.user?.name||'—'}}</td><td class="cell"><span class="rounded-full bg-slate-100 px-2 py-1 text-xs font-semibold text-slate-800">{{order.status}}</span></td><td class="cell text-right font-semibold text-slate-950">{{money(order.amount)}}</td><td class="cell"><Link :href="route('purchase-orders.show',order.id)" class="font-semibold text-amber-700">Voir</Link></td></tr><tr v-if="!orders.data.length"><td colspan="5" class="p-12 text-center text-slate-600">Aucun bon de commande lié.</td></tr></tbody></table></div><div v-if="orders.links?.length>3" class="flex gap-1 border-t p-4"><Link v-for="l in orders.links" :key="l.label" :href="l.url||'#'" preserve-scroll class="rounded-lg border px-3 py-2 text-sm" :class="l.active?'bg-slate-950 text-white':'text-slate-800'" v-html="l.label"/></div></section>
<aside class="card p-5"><div class="flex items-center gap-3"><UserRound class="h-6 w-6 text-amber-700"/><div><h2 class="font-bold text-slate-950">Responsable actuel</h2><p class="text-sm text-slate-600">Affectation suivie dans le temps</p></div></div><div class="my-5 rounded-xl p-4" :class="current?'bg-emerald-50':'bg-amber-50'"><template v-if="current"><strong class="text-slate-950">{{current.user?.name}}</strong><p class="text-sm text-slate-700">Depuis le {{date(current.starts_at)}}</p></template><p v-else class="font-semibold text-amber-900">Aucun responsable affecté</p></div><form class="space-y-4" @submit.prevent="assign"><div><label class="label">{{current?'Nouveau responsable':'Premier responsable'}}</label><SearchableCombobox v-model="assignment.user_id" :options="options" placeholder="Rechercher un utilisateur…"/><p v-if="assignment.errors.user_id" class="error">{{assignment.errors.user_id}}</p></div><div v-if="current"><label class="label">Date de fin du responsable actuel</label><input v-model="assignment.current_ends_at" type="date" required class="field"><p v-if="assignment.errors.current_ends_at" class="error">{{assignment.errors.current_ends_at}}</p></div><div><label class="label">Date de début du nouveau responsable</label><input v-model="assignment.starts_at" type="date" required class="field"><p v-if="assignment.errors.starts_at" class="error">{{assignment.errors.starts_at}}</p></div><p class="rounded-lg bg-blue-50 p-3 text-xs text-blue-900">Le nouveau mandat reste ouvert. Sa date de fin sera demandée uniquement lors du prochain remplacement.</p><button class="h-11 w-full rounded-xl bg-amber-600 font-semibold text-white hover:bg-amber-700" :disabled="assignment.processing">{{current?'Remplacer le responsable':'Affecter le responsable'}}</button></form></aside></div></template>
<section v-else class="card overflow-hidden"><div class="border-b p-5"><h2 class="text-lg font-bold text-slate-950">Historique des responsables</h2><p class="text-sm text-slate-600">Chaque période est conservée sans écraser les précédentes.</p></div><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left"><thead class="bg-slate-50 text-xs uppercase text-slate-700"><tr><th class="cell">Responsable</th><th class="cell">Rôle</th><th class="cell">Début</th><th class="cell">Fin</th><th class="cell">Affecté par</th><th class="cell">État</th></tr></thead><tbody class="divide-y divide-slate-200"><tr v-for="item in project.responsible_assignments" :key="item.id"><td class="cell"><strong class="text-slate-950">{{item.user?.name}}</strong><p class="text-xs text-slate-600">{{item.user?.email}}</p></td><td class="cell text-slate-800">{{item.user?.role?.name||'—'}}</td><td class="cell text-slate-800">{{date(item.starts_at)}}</td><td class="cell text-slate-800">{{date(item.ends_at)}}</td><td class="cell text-slate-800">{{item.assigner?.name||'—'}}</td><td class="cell"><span class="rounded-full px-3 py-1 text-xs font-semibold" :class="item.ends_at?'bg-slate-200 text-slate-800':'bg-emerald-100 text-emerald-800'">{{item.ends_at?'Terminé':'En cours'}}</span></td></tr><tr v-if="!project.responsible_assignments.length"><td colspan="6" class="p-12 text-center text-slate-600">Aucune affectation enregistrée.</td></tr></tbody></table></div></section>
</div></AppLayout></template>
<style scoped>.card{border:1px solid #e2e8f0;border-radius:1rem;background:#fff;box-shadow:0 1px 2px #0000000d}.stat{display:flex;align-items:center;gap:1rem;border:1px solid #e2e8f0;border-radius:1rem;background:#fff;padding:1.25rem}.stat strong{display:block;font-size:1.4rem;color:#020617}.stat span{display:block;font-size:.8rem;color:#475569}.icon{height:2rem;width:2rem}.tab{display:inline-flex;align-items:center;gap:.5rem;border-radius:.6rem;padding:.7rem 1rem;font-size:.875rem;font-weight:600;color:#475569}.tab.active{background:#fff;color:#020617;box-shadow:0 1px 2px #0001}.cell{padding:1rem 1.25rem}.label{margin-bottom:.25rem;display:block;font-size:.875rem;font-weight:600;color:#1e293b}.field{height:2.75rem;width:100%;border:1px solid #cbd5e1;border-radius:.75rem;background:#fff;padding:0 .8rem;color:#020617}.error{margin-top:.25rem;font-size:.75rem;color:#dc2626}</style>